@Composable
fun repeatScheduleLabel(interval: RepeatInterval, count: Int): String {
    if (count <= 1) {
        return when (interval) {
            RepeatInterval.DAILY -> stringResource(R.string.interval_daily)
            RepeatInterval.WEEKLY -> stringResource(R.string.interval_weekly)
            RepeatInterval.MONTHLY -> stringResource(R.string.interval_monthly)
            RepeatInterval.NONE -> stringResource(R.string.repeat_label_none)
        }
    }
    return when (interval) {
        RepeatInterval.DAILY -> pluralStringResource(R.plurals.repeat_every_days, count, count)
        RepeatInterval.WEEKLY -> pluralStringResource(R.plurals.repeat_every_weeks, count, count)
        RepeatInterval.MONTHLY -> pluralStringResource(R.plurals.repeat_every_months, count, count)
        RepeatInterval.NONE -> stringResource(R.string.interval_once)
    }
}
